_COMPARISON = re.compile(
    r"(?:历史|多样本).{0,24}(?:类似|相似|验证|回测|反例|失败|共性)|"
    r"(?:之前|过去|其他).{0,24}(?:行情|走势|板块|强势股|样本|题材).{0,24}(?:类似|相似|验证|回测|反例|失败|共性)|"
